# Make the example data files for the R cookbook from the published raw data
#
# Input:  data/mmc5.xlsx, the supplementary raw data table of
#         Garrido-Oter R, Nakano RT, Dombrowski N, Ma KW, McHardy AC, Schulze-Lefert P (2018).
#         Modular traits of the Rhizobiales root microbiota and their evolutionary relationship
#         with symbiotic rhizobia. Cell Host & Microbe 24(1): 155-167.e5.
#         https://doi.org/10.1016/j.chom.2018.06.006
#         The data in sheets "Fig S5A,B" and "Fig 5A" were generated by Nina Dombrowski.
# Output: data/Growth_Data.txt           (from sheet "Fig S5A,B")
#         data/Timecourse.txt            (from sheet "Fig 5A")
#         data/Genotype_Meristem.txt     (from sheet "Fig S6F")
#         data/Genotype_Rootlength.txt   (from sheet "Fig S6E")
#
# Changes compared to the Excel file:
# - shorter column names
# - nutrient labels shortened to low_P (50 uM phosphate) and high_P (625 uM phosphate)
# - values rounded to 2 decimals
# - columns not needed for the tutorial removed
# - growth data: only experiments ex61, ex64 and ex65 are kept. These are the only experiments
#   with the full design (mock, 129E and 13C under both nutrient levels, root length and
#   shoot weight measured). The other experiments contain only some of the treatments
#   (ex66 has no root lengths at all).
# - genotype data (Fig S6E, S6F): the genotype "arr1 arr12" is renamed to "arr1_arr12" (no space),
#   the column technical_replicate is removed
# Missing values are left as they are and are written as empty cells.
#
# Run from the project folder: Rscript data/make_example_data.R

library(readxl)


# ---- Growth data: sheet "Fig S5A,B" ----

# the first line of the sheet is a comment, so we skip it
# the text "NA" in the number columns means a missing value
growth_raw <- read_excel("data/mmc5.xlsx", sheet = "Fig S5A,B", skip = 1, na = c("", "NA"))

cat("Growth data, raw:", nrow(growth_raw), "rows,", ncol(growth_raw), "columns\n")
print(colnames(growth_raw))
print(table(growth_raw$Nutrient, useNA = "ifany"))

# make the new table column by column
growth_data <- data.frame(
  Nutrient    = NA,
  Condition   = growth_raw$Treatment,
  Experiment  = growth_raw$experiment_id,
  Rootlength  = round(growth_raw$`Primary Root Length (mm)`, 2),
  FW_shoot_mg = round(growth_raw$`Shoot Fresh Weight (mg)`, 2)
)

# shorten the nutrient labels (the sheet says mM, but the concentrations are uM)
growth_data$Nutrient[growth_raw$Nutrient == "50 mM P"]  <- "low_P"
growth_data$Nutrient[growth_raw$Nutrient == "625 mM P"] <- "high_P"

# check which treatments were measured in which experiment (root length present)
print(table(growth_data$Experiment[!is.na(growth_data$Rootlength)],
            paste(growth_data$Nutrient, growth_data$Condition)[!is.na(growth_data$Rootlength)]))

# keep only the experiments with the full design
keep <- growth_data$Experiment == "ex61" | growth_data$Experiment == "ex64" | growth_data$Experiment == "ex65"
growth_data <- growth_data[keep, ]
rownames(growth_data) <- NULL

cat("\nGrowth data, new:", nrow(growth_data), "rows,", ncol(growth_data), "columns\n")
print(table(growth_data$Condition, growth_data$Nutrient, useNA = "ifany"))
cat("Missing values per column:\n")
print(colSums(is.na(growth_data)))
print(head(growth_data))

# open the file in binary mode ("wb"), so that R writes Unix line endings on every system;
# then the file size is the same on GitHub and on every computer (see download step in the book)
out <- file("data/Growth_Data.txt", open = "wb")
write.table(growth_data, out, sep = "\t", row.names = FALSE, quote = FALSE, na = "")
close(out)


# ---- Timecourse data: sheet "Fig 5A" ----

timecourse_raw <- read_excel("data/mmc5.xlsx", sheet = "Fig 5A", skip = 1)

cat("\n\nTimecourse, raw:", nrow(timecourse_raw), "rows,", ncol(timecourse_raw), "columns\n")
print(colnames(timecourse_raw))
print(table(timecourse_raw$Nutrient, useNA = "ifany"))

timecourse <- data.frame(
  Nutrient   = NA,
  Condition  = timecourse_raw$Condition,
  Timepoint  = timecourse_raw$Timepoint,
  Rootlength = round(timecourse_raw$Rootlength, 2)
)

# shorten the nutrient labels
# (we only compare the start of the label, to avoid typing the micro sign)
timecourse$Nutrient[startsWith(timecourse_raw$Nutrient, "Low Pi")]  <- "low_P"
timecourse$Nutrient[startsWith(timecourse_raw$Nutrient, "High Pi")] <- "high_P"

cat("\nTimecourse, new:", nrow(timecourse), "rows,", ncol(timecourse), "columns\n")
print(table(timecourse$Condition, timecourse$Timepoint, timecourse$Nutrient, useNA = "ifany"))
cat("Missing values per column:\n")
print(colSums(is.na(timecourse)))
print(head(timecourse))

out <- file("data/Timecourse.txt", open = "wb")
write.table(timecourse, out, sep = "\t", row.names = FALSE, quote = FALSE, na = "")
close(out)


# ---- Genotype data, meristem cells: sheet "Fig S6F" ----

meristem_raw <- read_excel("data/mmc5.xlsx", sheet = "Fig S6F", skip = 1)

cat("\n\nMeristem data, raw:", nrow(meristem_raw), "rows,", ncol(meristem_raw), "columns\n")
print(colnames(meristem_raw))

meristem <- data.frame(
  Genotype       = meristem_raw$genotype,
  Condition      = meristem_raw$treatment,
  Meristem_cells = meristem_raw$`#Meristematic cells`
)

# remove the space in the genotype name
meristem$Genotype[meristem$Genotype == "arr1 arr12"] <- "arr1_arr12"

cat("\nMeristem data, new:", nrow(meristem), "rows,", ncol(meristem), "columns\n")
print(table(meristem$Genotype, meristem$Condition, useNA = "ifany"))
cat("Missing values per column:\n")
print(colSums(is.na(meristem)))
print(head(meristem))

out <- file("data/Genotype_Meristem.txt", open = "wb")
write.table(meristem, out, sep = "\t", row.names = FALSE, quote = FALSE, na = "")
close(out)


# ---- Genotype data, root length: sheet "Fig S6E" ----

genotype_root_raw <- read_excel("data/mmc5.xlsx", sheet = "Fig S6E", skip = 1)

cat("\n\nGenotype root data, raw:", nrow(genotype_root_raw), "rows,", ncol(genotype_root_raw), "columns\n")
print(colnames(genotype_root_raw))

# note: the column name in the sheet has a typo ("Roog")
genotype_root <- data.frame(
  Genotype   = genotype_root_raw$genotype,
  Condition  = genotype_root_raw$treatment,
  Rootlength = round(genotype_root_raw$`Primary Roog Length (mm)`, 2)
)

genotype_root$Genotype[genotype_root$Genotype == "arr1 arr12"] <- "arr1_arr12"

cat("\nGenotype root data, new:", nrow(genotype_root), "rows,", ncol(genotype_root), "columns\n")
print(table(genotype_root$Genotype, genotype_root$Condition, useNA = "ifany"))
cat("Missing values per column:\n")
print(colSums(is.na(genotype_root)))
print(head(genotype_root))

out <- file("data/Genotype_Rootlength.txt", open = "wb")
write.table(genotype_root, out, sep = "\t", row.names = FALSE, quote = FALSE, na = "")
close(out)
